-- RAKHAL-269: trim ProductionStatus to MILKING|DRY only (was
-- MILKING|DRY|FRESH|GROWING|SOLD|DECEASED — overloaded with lifecycle states
-- that already have a correct home in CattleStatus + Cattle.isActive). Also
-- adds CULLED to CattleStatus.
--
-- v2 correction: dropped the Cattle.lactationStartDate column this migration
-- originally added — v2 review found it a duplicate source of truth against
-- the already-existing `Lactation.startDate`; lactation start now lives only
-- on `Lactation` (+ `startReason`/`sourceCalvingEventId`, RAKHAL-271).
--
-- Hand-authored (not autogenerated) because it drops enum values with existing
-- data — additive steps run non-interactively via `migrate dev`, but a
-- value-dropping migration needs this expand -> backfill -> contract shape
-- applied via `migrate deploy` per repo convention (mirrors
-- 20260719120000_feed_taxonomy_unification's rename+CASE-cast style).

-- ==== CattleStatus: additive CULLED value ===================================

ALTER TYPE "CattleStatus" ADD VALUE 'CULLED';

-- ==== ProductionStatus: rename old type, create new 2-value type, cast ======

-- Rename the old 6-value type out of the way.
ALTER TYPE "ProductionStatus" RENAME TO "ProductionStatus_old";

-- Create the new, trimmed type.
CREATE TYPE "ProductionStatus" AS ENUM ('MILKING', 'DRY');

-- Cast the column through a CASE: only MILKING/DRY survive as-is; any row
-- carrying the old lifecycle-overloaded values (FRESH/GROWING/SOLD/DECEASED)
-- becomes NULL — that lifecycle information already lives on
-- Cattle.status/isActive, so nothing is lost.
ALTER TABLE "Cattle"
  ALTER COLUMN "productionStatus" DROP DEFAULT,
  ALTER COLUMN "productionStatus" TYPE "ProductionStatus" USING (
    CASE "productionStatus"::text
      WHEN 'MILKING' THEN 'MILKING'
      WHEN 'DRY' THEN 'DRY'
      ELSE NULL
    END
  )::"ProductionStatus",
  ALTER COLUMN "productionStatus" DROP NOT NULL;

-- Drop the old 6-value type.
DROP TYPE "ProductionStatus_old";
